// Check computes the CRC32 of the file at Path and returns whether it
// matches the stored CRC32 value.
func (hf *ChecksummedFile) Check() (bool, error) {
	actual, err := rsum.CRC32(hf.Path)
	if err != nil {
		return false, err
	}
	return actual == hf.CRC32, nil
}

